function spawnCloud() {
  const radius = 20 + Math.random() * 30;
  const y = 20 + Math.random() * (height / 3);
  clouds.push({ x: width, y, r: radius });
}

function updateClouds() {
  for (let i = clouds.length - 1; i >= 0; i--) {
    const c = clouds[i];
    c.x -= cloudSpeed;
    if (c.x + c.r < 0) clouds.splice(i, 1);
  }
}

